"""Exact pinned ArmCpu transformation (guamp): SMP, self-IPI and pending-mode SGIs default on since 28/10 (=0 off)."""
from pathlib import Path
import hashlib,json,sys
ORIGINAL_SHA256 = '3c87b3bd617be5582a6a24ff797c359497ee9feaa702ee883ecee4270db21c9f'
PATCHED_SHA256 = '19574d606ed22ad2e9f3c81ef46662d7363d3bd93b0fdd1200b9951a989837ab'
EDITS = [('static bool gSpiIpi = false;', 'static bool gPendingIpi = false; // opt-in guamp-ipi-pending=1: SGI0 through target GICR_ISPENDR0\nstatic bool gSpiIpi = false;'), ('volatile uint64_t armcpu_ipi_selftest_sent = 0;', 'volatile uint64_t armcpu_ipi_selftest_sent = 0;\nvolatile uint32_t armcpu_ipi_pending_mode = 0;'), ('  gSelfIpi = selfIpi == 1;', '  gSelfIpi = selfIpi == 1;\n  unsigned pendingIpi = 1; // default on (verified 28/10): guamp-ipi-pending=0 keeps ICC_SGI1R\n  PE_parse_boot_argn ("guamp-ipi-pending", &pendingIpi, sizeof (pendingIpi));\n  gPendingIpi = pendingIpi == 1;\n  armcpu_ipi_pending_mode = gPendingIpi ? 1 : 0;'), ('  if (gSpiIpi) { spiIpiSend (gDist, peer->logicalId & 7); return; }', '  if (gPendingIpi) {\n    // GICv3: each redistributor\'s SGI frame +0x0200 sets SGI/PPI pending.\n    // Use the frame found for this target\'s MPIDR, never a logical-ID stride.\n    // W1S: do not read/modify/write or pend unrelated interrupts.\n    if (peer->redist == 0) { panic ("ArmCpu: IPI target redistributor unavailable"); }\n    __asm__ volatile ("dsb ishst" ::: "memory");\n    write32 (peer->redist + 0x10000, 0x200, 1U);\n    __asm__ volatile ("dsb sy; isb" ::: "memory");\n    return;\n  }\n  if (gSpiIpi) { spiIpiSend (gDist, peer->logicalId & 7); return; }'), ('extern "C" void rtclock_intr (unsigned int);', 'extern "C" void rtclock_intr (unsigned int);\nextern "C" void guamp_native_timer_intr (unsigned int, unsigned int);'), ('static bool gSpiIpi = false;', 'static unsigned gTimerContract = 0; // 0=original,1=native FIQ contract+sample,2=sample only\nstatic bool gSpiIpi = false;'), ('  gSelfIpi = selfIpi == 1;', '  gSelfIpi = selfIpi == 1;\n  unsigned timerMode = 0;\n  PE_parse_boot_argn ("guamp-timer-contract", &timerMode, sizeof (timerMode));\n  gTimerContract = timerMode <= 2 ? timerMode : 0;'), ('      rtclock_intr (0);', '      if (gTimerContract) { guamp_native_timer_intr (logicalId, gTimerContract); }\n      else { rtclock_intr (0); }')]
EDITS += [('static bool gSpiIpi = false;', 'static unsigned gIrqTrace = 0; // opt-in read-only IRQ lifecycle\nstatic bool gSpiIpi = false;'), ('  gSelfIpi = selfIpi == 1;', '  gSelfIpi = selfIpi == 1;\n  PE_parse_boot_argn ("guamp-irq-trace", &gIrqTrace, sizeof (gIrqTrace));'), ('void ArmCpu::interrupt (void)', '\n// Read-only, once per second at most; never acknowledge an extra interrupt.\nextern "C" {\nvolatile uint64_t guamp_irq_trace[8][3][14] = {};\nvolatile uint32_t guamp_irq_trace_sequence[8] = {};\n}\nstatic bool guampIrqPoint(unsigned cpu, uintptr_t frame, uint64_t iar, unsigned phase)\n{\n  static uint64_t last[8];\n  if (gIrqTrace != 1 || cpu >= 8 || phase >= 3) return false;\n  if (phase == 0) {\n    const uint32_t count = armcpu_core_timer[cpu];\n    if (count != 1 && (count & 65535U) != 0) return false;\n    uint64_t now = __builtin_arm_rsr64("CNTVCT_EL0");\n    uint64_t frequency = __builtin_arm_rsr64("CNTFRQ_EL0");\n    if (last[cpu] && now - last[cpu] < frequency) return false;\n    last[cpu] = now;\n    __atomic_add_fetch(&guamp_irq_trace_sequence[cpu], 1, __ATOMIC_ACQ_REL);\n  }\n  __asm__ volatile ("dsb sy; isb" ::: "memory");\n  volatile uint64_t *r = guamp_irq_trace[cpu][phase];\n  r[0] = __builtin_arm_rsr64("CNTVCT_EL0");\n  r[1] = __builtin_arm_rsr64("CNTV_CVAL_EL0");\n  r[2] = __builtin_arm_rsr64("CNTV_CTL_EL0");\n  r[3] = __builtin_arm_rsr64("CNTP_CVAL_EL0");\n  r[4] = __builtin_arm_rsr64("CNTP_CTL_EL0");\n  r[5] = read32(frame + 0x10000, 0x200);\n  r[6] = read32(frame + 0x10000, 0x300);\n  r[7] = read32(frame + 0x10000, 0xc04);\n  r[8] = __builtin_arm_rsr64("ICC_CTLR_EL1");\n  r[9] = __builtin_arm_rsr64("ICC_RPR_EL1");\n  r[10] = __builtin_arm_rsr64("ICC_HPPIR1_EL1");\n  r[11] = iar;\n  r[12] = __builtin_arm_rsr64("MPIDR_EL1");\n  r[13] = __builtin_arm_rsr64("CNTFRQ_EL0");\n  if (phase == 2) __atomic_add_fetch(&guamp_irq_trace_sequence[cpu], 1, __ATOMIC_RELEASE);\n  return true;\n}\n\nvoid ArmCpu::interrupt (void)'), ('    uint64_t id;\n', '    bool traceTimer = false;\n    uint64_t id;\n'), ('      armcpu_irq_phase=2;', '      traceTimer = guampIrqPoint(logicalId, redist, id, 0);\n      armcpu_irq_phase=2;'), ('      armcpu_irq_phase=3;', '      if (traceTimer) guampIrqPoint(logicalId, redist, id, 1);\n      armcpu_irq_phase=3;'), ('    __asm__ volatile ("msr icc_eoir1_el1, %0; isb" :: "r" (id) : "memory");', '    __asm__ volatile ("msr icc_eoir1_el1, %0; isb" :: "r" (id) : "memory");\n    if (traceTimer) guampIrqPoint(logicalId, redist, id, 2);')]

# SM6115 wires CNTV (EL1 virtual timer) to PPI 3 = INTID 19 (bengal.dtsi timer: <1 1>,<1 2>,<1 3>,<1 0>
# = sec-phys 17, ns-phys 18, virt 19, hyp 16). INTID 27 is the SBSA number, not this SoC's: it is a
# level input that stays asserted, so taking it was a storm. Enable/dispatch 19 and leave 27 disabled.
EDITS += [('static const uint32_t kSgiPpiEnable = 0xffffU | (1U << 27);', 'static const uint32_t kSgiPpiEnable = 0xffffU | (1U << 19); // SM6115 CNTV = PPI 3 = INTID 19'), ('    if ((id & 0xffffff) == 27) {', '    if ((id & 0xffffff) == 19) {')]
# Verified 28/10 (kernel-gpu11..bt11): secondary cores and the self-IPI check are code defaults; =0 turns each off.
EDITS += [('    unsigned smp = 0;\n    PE_parse_boot_argn ("sheng-smp", &smp, sizeof (smp));', '    unsigned smp = 1; // default on (guamp, verified 28/10): sheng-smp=0 keeps one core\n    PE_parse_boot_argn ("sheng-smp", &smp, sizeof (smp));'), ('  unsigned smp = 0;\n  PE_parse_boot_argn ("sheng-smp", &smp, sizeof (smp));', '  unsigned smp = 1; // default on (guamp, verified 28/10)\n  PE_parse_boot_argn ("sheng-smp", &smp, sizeof (smp));'), ('  unsigned selfIpi = 0;\n', '  unsigned selfIpi = 1; // default on (guamp, verified 28/10): armcpu-self-ipi=0 skips it\n')]
def transform(data):
    digest = hashlib.sha256(data).hexdigest()
    if digest == PATCHED_SHA256: return data
    assert digest == ORIGINAL_SHA256, 'Refuse an unreviewed ArmCpu revision'
    text = data.decode()
    for old,new in EDITS:
        assert text.count(old) == 1
        text = text.replace(old,new)
    result = text.encode()
    assert hashlib.sha256(result).hexdigest() == PATCHED_SHA256
    return result
if __name__ == '__main__':
    path = Path(sys.argv[1]) if len(sys.argv)>1 else Path(__file__).resolve().parents[1]/'drivers/ArmCpu/ArmCpu.cpp'
    path.write_bytes(transform(path.read_bytes()))
    print('ArmCpu: verified guamp variant (sheng-smp, armcpu-self-ipi, guamp-ipi-pending default 1)')
